import re


_API_KEY = re.compile(r"\b(?:key-|sk-|tok_)[A-Za-z0-9]{12,}\b", re.IGNORECASE)
_DEBUG_LOGGER = re.compile(r"^\s*DEBUG_")


def redact(text: str) -> str:
    """Mask API keys, except on lines emitted by DEBUG_ loggers."""
    return "".join(
        line if _DEBUG_LOGGER.match(line) else _API_KEY.sub("***", line)
        for line in text.splitlines(keepends=True)
    )

